// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(c).balance);
        vm.assume(target != address(0));
        vm.assume(target != address(c));

        vm.deal(address(this), 1 ether);
        vm.deal(address(c), 1 ether);

        c.sendMoney(target, value);

        (, bytes memory data) = address(c).call{value: 1}('');
        (bool success, ) = address(c).call{value: 1}('');
        assertTrue(success);
    }
}

